package com.yuegang.zhihui.system.application;
import com.yuegang.zhihui.system.domain.*;import com.yuegang.zhihui.system.infrastructure.*;import com.yuegang.zhihui.system.security.*;import java.time.*;import java.util.*;import javax.sql.*;import org.springframework.beans.factory.annotation.*;import org.springframework.context.annotation.*;
@Configuration(proxyBeanMethods=false) class SystemConfiguration{@Bean AuthorizationRepository authorizationRepository(DataSource d){return new JdbcAuthorizationRepository(d);}@Bean AuthorizationService authorizationService(AuthorizationRepository r){return new AuthorizationService(r);}@Bean SystemSettingService systemSettingService(DataSource d){return new SystemSettingService(d);}@Bean SystemCatalogService systemCatalogService(DataSource d){return new SystemCatalogService(d);}@Bean SystemTrustedUserContextResolver systemTrustedUserContextResolver(@Value("${ygh.internal-request.hmac-base64}")String encoded,Clock c){byte[]s=Base64.getDecoder().decode(encoded);try{return new SystemTrustedUserContextResolver(s,c);}finally{Arrays.fill(s,(byte)0);}}@Bean InternalServiceVerifier internalServiceVerifier(@Value("${ygh.internal-request.hmac-base64}")String encoded,Clock c){byte[]s=Base64.getDecoder().decode(encoded);try{return new InternalServiceVerifier(s,c);}finally{Arrays.fill(s,(byte)0);}}@Bean Clock systemClock(){return Clock.systemUTC();}}
